// Generated by `tt generate` — do not edit; this file is overwritten on every run.
import { test as base, expect, type Locator, type Page, type Response } from '@playwright/test';

export { expect };

/** Credentials per role, from tathya.config.yaml. */
export const roleCredentials = {
  "admin": {
    "username": "admin@example.com",
    "password": "password"
  },
  "user": {
    "username": "user@example.com",
    "password": "password"
  }
} as const;
export type Role = keyof typeof roleCredentials;

const loginPath = "/login";
const errorSelector = ".invalid-feedback, [role=alert], .text-red-600, x-input-error p";
const resetHook: { method: 'POST' | 'GET' | 'DELETE'; path: string } | null = {"method":"POST","path":"/__testing/reset"};

export type App = {
  /** Reset app data (when the app has a reset hook), drop the session, and log in as `role`. */
  loginAs(role: Role): Promise<void>;
  /** Read-only runs: reuse the project's stored session when it is still valid, else log in — never reset. */
  ensureLoggedIn(role: Role): Promise<void>;
  /** Call the app's reset hook, if one is configured. */
  resetData(): Promise<void>;
};

/**
 * `test` with two extra fixtures: `role` — the role of the current Playwright project
 * (`admin-chromium` → `admin`), used to gate role-specific groups — and `app`, the
 * authenticated-session helper.
 */
export const test = base.extend<{ role: string; app: App }>({
  role: async ({}, use, testInfo) => {
    await use(testInfo.project.name.split('-')[0] ?? '');
  },
  app: async ({ page }, use) => {
    await use({
      loginAs: (role) => loginAs(page, role),
      ensureLoggedIn: (role) => ensureLoggedIn(page, role),
      resetData: () => resetAppData(page),
    });
  },
});

export async function resetAppData(page: Page): Promise<void> {
  if (!resetHook) return;
  await page.request.fetch(resetHook.path, { method: resetHook.method });
}

export async function loginAs(page: Page, role: Role): Promise<void> {
  await resetAppData(page);
  await page.context().clearCookies();
  const credentials = roleCredentials[role];
  await performLogin(page, credentials.username, credentials.password);
  await assertLoggedIn(page);
}

/**
 * Open the login page: an app that still has a valid session (the project's storageState) sends
 * an authenticated visitor elsewhere, so nothing more to do; otherwise log in. No reset hook.
 */
export async function ensureLoggedIn(page: Page, role: Role): Promise<void> {
  await page.goto(loginPath);
  await page.waitForLoadState('domcontentloaded').catch(() => undefined);
  const expectedLoginPath = new URL(loginPath, 'http://tathyatest.local').pathname;
  const passwordField = page.locator('input[type="password"]').first();
  if (new URL(page.url()).pathname !== expectedLoginPath || !(await passwordField.isVisible().catch(() => false))) return;
  const credentials = roleCredentials[role];
  await performLogin(page, credentials.username, credentials.password);
  await assertLoggedIn(page);
}

export async function performLogin(page: Page, username: string, password: string): Promise<void> {
  await page.goto(loginPath);
  const controls = await inferLoginControls(page);
  await loginLocator(page, controls.username).fill(username);
  await loginLocator(page, controls.password).fill(password);
  const beforePath = new URL(page.url()).pathname;
  await Promise.all([
    page.waitForURL((url) => url.pathname !== beforePath, { timeout: 5000 }).catch(() => undefined),
    loginLocator(page, controls.submit).click(),
  ]);
  await page.waitForLoadState('networkidle', { timeout: 5000 }).catch(() => undefined);
}

/** Logged in = we left the login page, or the password field is gone. */
export async function assertLoggedIn(page: Page): Promise<void> {
  const expectedLoginPath = new URL(loginPath, 'http://tathyatest.local').pathname;
  // A slow browser (WebKit under load) may still be mid-redirect after the click; give it time to
  // leave the login page before judging. Only successful-login paths call this, so rejected logins stay fast.
  await page.waitForURL((url) => url.pathname !== expectedLoginPath, { timeout: 15000 }).catch(() => undefined);
  if (new URL(page.url()).pathname !== expectedLoginPath) return;
  await expect(page.locator('input[type="password"], input[autocomplete="current-password"], input[name*="password"], input[id*="password"], input[placeholder*="Password"]').first()).not.toBeVisible();
}

/**
 * Logged out = a page that needed the session is no longer reachable: revisiting it lands on
 * the login page, shows a login form, or redirects elsewhere. (Where the app sends you right
 * after logging out — home, login, a goodbye page — is app-specific and not asserted.)
 */
export async function assertLoggedOut(page: Page, protectedPath: string): Promise<void> {
  await page.waitForLoadState('domcontentloaded').catch(() => undefined);
  await page.goto(protectedPath);
  await page.waitForLoadState('networkidle', { timeout: 5000 }).catch(() => undefined);
  const expectedLoginPath = new URL(loginPath, 'http://tathyatest.local').pathname;
  const landed = new URL(page.url()).pathname;
  if (landed === expectedLoginPath) return;
  const loginForm = page.locator('input[type="password"], input[autocomplete="current-password"], input[name*="password"]').first();
  if (await loginForm.isVisible().catch(() => false)) return;
  expect(landed, 'a protected page is still reachable after logging out').not.toBe(new URL(protectedPath, 'http://tathyatest.local').pathname);
}

/** A rejected login shows the app's error indicator and stays on the login form. */
export async function assertLoginRejected(page: Page): Promise<void> {
  await expect(page.locator(errorSelector).first()).toBeVisible();
  expect(new URL(page.url()).pathname, 'a rejected login left the login page').toBe(new URL(loginPath, 'http://tathyatest.local').pathname);
  await expect(page.locator('input[type="password"]').first()).toBeVisible();
}

/** A stable number per name, added to the faker seed so every project draws its own values. */
export function seedOffset(name: string): number {
  return Array.from(name).reduce((hash, char) => (hash * 31 + char.charCodeAt(0)) % 100000, 0);
}

/** A small in-memory file of the given MIME type for `setInputFiles` (no fixture files on disk). */
export function uploadFixture(mimeType: string): { name: string; mimeType: string; buffer: Buffer } {
  const extension = { 'image/png': 'png', 'image/jpeg': 'jpg', 'image/gif': 'gif', 'application/pdf': 'pdf', 'text/plain': 'txt', 'text/csv': 'csv', 'application/json': 'json' }[mimeType] ?? 'bin';
  const content = mimeType === 'image/png'
    ? Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==', 'base64')
    : mimeType === 'application/pdf'
      ? Buffer.from('%PDF-1.4\n1 0 obj<</Type/Catalog>>endobj\ntrailer<</Root 1 0 R>>\n%%EOF\n')
      : Buffer.from('TathyaTest upload fixture\n');
  return { name: 'tathyatest-upload.' + extension, mimeType, buffer: content };
}

/**
 * A GET (search/filter) form round-trips its fields into the URL: every submitted value must
 * come back in the query string (an empty value may be omitted by the app).
 */
export async function expectQueryEcho(page: Page, params: Record<string, string>, path: string): Promise<void> {
  await expect(page).toHaveURL((url) => url.pathname === path);
  await page.waitForLoadState('domcontentloaded').catch(() => undefined);
  const query = new URL(page.url()).searchParams;
  for (const [key, value] of Object.entries(params)) {
    const actual = query.get(key);
    if (value === '') expect(actual === null || actual === '').toBe(true);
    else expect(actual, 'query parameter ' + key).toBe(value);
  }
  await expectNoServerError(page);
}

/** Reopening the edit page shows the submitted value: the update was stored, not only accepted. */
export async function expectValuePersisted(page: Page, url: string, field: Locator, value: string): Promise<void> {
  await page.goto(url);
  await expect(field.first()).toHaveValue(value);
}

/** The app accepted the submission: once it has answered, no form shows an invalid field or error. */
export async function expectNoValidationError(page: Page): Promise<void> {
  await page.waitForLoadState('networkidle', { timeout: 5000 }).catch(() => undefined);
  await expect.poll(
    () => page.evaluate(countValidationErrors, { selector: errorSelector }),
    { message: 'a form shows a validation error' },
  ).toBe(0);
}

/**
 * Invalid fields and error indicators shown inside forms. Messages outside forms (a success flash
 * with `role=alert`) and styled controls (a red "Delete" button) are not validation errors.
 */
function countValidationErrors({ selector, root }: { selector: string; root?: Document }): number {
  const doc = root ?? document;
  const controls = 'button, a, input, select, textarea, [role="button"]';
  const shown = (el: Element): boolean => el.getClientRects().length > 0 && doc.defaultView?.getComputedStyle(el).visibility !== 'hidden';
  return Array.from(doc.querySelectorAll('form')).flatMap((form) => [
    ...Array.from(form.querySelectorAll('[aria-invalid="true"], :user-invalid')),
    ...Array.from(form.querySelectorAll(selector)).filter((el) => !el.closest(controls) && (el.textContent ?? '').trim() !== ''),
  ]).filter(shown).length;
}

/**
 * A fieldless state-change form (toggle done/undone, archive, publish) proves it worked by its
 * own submit control reading differently afterwards; a control that disappeared (the row moved
 * to another list) is accepted too.
 */
export async function expectStateFlipped(page: Page, formSelector: string, before: string | null): Promise<void> {
  await page.waitForLoadState('domcontentloaded').catch(() => undefined);
  const control = page.locator(formSelector).first();
  if (before && (await control.count()) > 0) await expect(control).not.toContainText(before);
  await expectNoServerError(page);
}

/**
 * The page settled and is not a server-error page. The response status is the primary signal; the
 * text check only looks at error-page shapes (the title, or an explicit "server error" phrase), so
 * a healthy page that merely mentions "500" or "exception" in its content does not fail.
 */
export async function expectNoServerError(page: Page, response?: Response | null): Promise<void> {
  if (response) expect(response.status(), 'server answered ' + response.status()).toBeLessThan(500);
  await page.waitForLoadState('domcontentloaded').catch(() => undefined);
  await page.waitForLoadState('networkidle', { timeout: 5000 }).catch(() => undefined);
  const title = await page.title().catch(() => '');
  expect(title, 'page title looks like a server error').not.toMatch(/^\s*5\d\d\b|server error|\b[A-Z]\w*Exception\b/);
  await expect(page.locator('body')).not.toContainText(/(internal )?server error|whoops, looks like something went wrong/i);
}

/**
 * Allowed = a healthy (< 400) document response, OR — because SPA hosts serve deep links with a
 * 404 while the client router still renders the page — staying on the route with interactive
 * content rendered. Any other error status, and a genuine 404 page, fails.
 */
export async function expectRouteAllowed(page: Page, response: Response | null, routePath: string): Promise<void> {
  const status = response?.status() ?? 200;
  if (status >= 400) {
    // Only a 404 can be an app shell served for a deep link; a denial stays a denial.
    expect(status, 'server answered ' + status).toBe(404);
    await page.waitForLoadState('networkidle', { timeout: 5000 }).catch(() => undefined);
    expect(new URL(page.url()).pathname).toBe(routePath);
    expect(await page.locator('a, button, form, select, input').count()).toBeGreaterThan(0);
  }
  await expectNoServerError(page, response);
}

/**
 * A route the generator inferred from REST conventions (`/todos/7/edit` ⇒ `/todos/7`) rather than
 * crawled. An app that simply has no such page answers 404 — nothing to test, skip. A 5xx is a
 * declared-but-broken route and fails like any other.
 */
export async function expectInferredRouteOpens(page: Page, response: Response | null, routePath: string): Promise<void> {
  const status = response?.status() ?? 200;
  // 405: the path exists for other verbs only. 404 with no app content behind it: no such page.
  // Either way the convention does not hold for this app. Same-origin links/forms are the signal —
  // a framework debug page has buttons and external links but no app navigation.
  test.skip(status === 405, 'inferred route is not implemented by the app (HTTP 405)');
  if (status === 404) {
    const sameOriginLinks = await page.locator('a[href]').evaluateAll((anchors) => anchors.filter((anchor) => (anchor as HTMLAnchorElement).origin === location.origin).length);
    const navigable = sameOriginLinks + (await page.locator('form, select').count());
    test.skip(navigable === 0, 'inferred route is not implemented by the app (HTTP ' + status + ')');
  }
  await expectRouteAllowed(page, response, routePath);
}

/**
 * Blocked = a direct denial status, or — since page.goto resolves redirect chains — a 2xx on a
 * DIFFERENT path; either way the body is graceful.
 */
export async function expectRouteBlocked(page: Page, response: Response | null, blockedPath: string): Promise<void> {
  const status = response?.status() ?? 200;
  if (status < 400) {
    expect(new URL(page.url()).pathname).not.toBe(blockedPath);
  } else {
    expect([401, 403, 404]).toContain(status);
  }
  await expectNoServerError(page, response);
}

function loginLocator(page: Page, locator: LoginLocator) {
  switch (locator.strategy) {
    case 'testid':
      return page.getByTestId(locator.value);
    case 'role': {
      const [role, ...nameParts] = locator.value.split(':');
      const name = nameParts.join(':');
      return name ? page.getByRole(role as Parameters<typeof page.getByRole>[0], { name }) : page.getByRole(role as Parameters<typeof page.getByRole>[0]);
    }
    case 'label':
      return page.getByLabel(locator.value, { exact: true });
    case 'placeholder':
      return page.getByPlaceholder(locator.value);
    case 'id':
      return page.locator('#' + cssEscape(locator.value));
    case 'name':
      return page.locator('[name="' + cssEscape(locator.value) + '"]');
    case 'css':
      return page.locator(locator.value);
  }
}

// <tathya:login-infer>
export type LoginLocator = { strategy: 'testid' | 'role' | 'label' | 'placeholder' | 'id' | 'name' | 'css'; value: string };
export type LoginControls = { username: LoginLocator; password: LoginLocator; submit: LoginLocator };

/** `root` is the login page's document; pass null to use the document the code runs in. */
export function loginControlsOfDocument(root: Document | null): LoginControls {
  type Candidate = {
    tag: 'input' | 'button';
    type: string;
    name: string;
    id: string;
    placeholder: string;
    autocomplete: string;
    ariaLabel: string;
    dataAttr: string;
    dataValue: string;
    text: string;
  };
  const doc = root ?? document;
  const attr = (el: Element, name: string): string => el.getAttribute(name) ?? '';
  const visible = (el: Element): boolean =>
    el.getClientRects().length > 0 && doc.defaultView?.getComputedStyle(el).visibility !== 'hidden';
  const candidate = (el: Element): Candidate => {
    const tag = el.tagName.toLowerCase() === 'button' ? 'button' : 'input';
    const dataAttr = attr(el, 'data-test') ? 'data-test' : attr(el, 'data-testid') ? 'data-testid' : '';
    return {
      tag,
      // A <button> without a type submits its form.
      type: (attr(el, 'type') || (tag === 'button' ? 'submit' : 'text')).toLowerCase(),
      name: attr(el, 'name'),
      id: attr(el, 'id'),
      placeholder: attr(el, 'placeholder'),
      autocomplete: attr(el, 'autocomplete').toLowerCase(),
      ariaLabel: attr(el, 'aria-label'),
      dataAttr,
      dataValue: dataAttr ? attr(el, dataAttr) : '',
      text: tag === 'button' ? (el.textContent ?? '').replace(/\s+/g, ' ').trim() : attr(el, 'value'),
    };
  };
  const haystack = (c: Candidate): string =>
    [c.type, c.name, c.id, c.placeholder, c.autocomplete, c.ariaLabel, c.dataValue, c.text].join(' ').toLowerCase();
  const best = (candidates: Candidate[], score: (c: Candidate) => number): Candidate | undefined =>
    candidates
      .map((c) => ({ c, points: score(c) }))
      .filter(({ points }) => points > 0)
      .sort((a, b) => b.points - a.points)[0]?.c;
  /** Prefer what a user can see; a page that shows nothing yet still yields its elements. */
  const shown = (elements: Element[]): Candidate[] => {
    const onScreen = elements.filter(visible);
    return (onScreen.length > 0 ? onScreen : elements).map(candidate);
  };

  const skipped = ['hidden', 'submit', 'button', 'reset', 'image', 'file'];
  const inputs = shown(Array.from(doc.querySelectorAll('input')).filter((el) => !skipped.includes(attr(el, 'type').toLowerCase()) && !el.disabled));
  const buttons = shown(Array.from(doc.querySelectorAll('button, input[type="submit"], input[type="button"]')));

  const password = best(inputs, (c) => (c.type === 'password' ? 100 : 0) + (/(password|passcode|pin)/.test(haystack(c)) ? 50 : 0));
  const others = inputs.filter((c) => c !== password);
  const username = best(others, (c) =>
    (c.type === 'email' ? 100 : 0)
    + (c.autocomplete === 'username' ? 90 : 0)
    + (c.autocomplete === 'email' ? 80 : 0)
    + (/(email|username|user|account|identifier|handle)/.test(haystack(c)) ? 50 : 0))
    ?? others.find((c) => ['text', 'tel', 'number', 'search'].includes(c.type));
  const submit = best(buttons, (c) =>
    (c.dataValue ? 100 : 0)
    + (c.tag === 'button' ? 20 : 0)
    + (/(log in|login|sign in|sign-in)/.test(haystack(c)) ? 50 : 0)
    + (c.type === 'submit' ? 10 : 0)) ?? buttons[0];

  const locatorFor = (c: Candidate | undefined, fallback: string): LoginLocator => {
    if (!c) return { strategy: 'css', value: fallback };
    if (c.dataValue) {
      const escaped = c.dataValue.replace(/["\\]/g, '\\$&');
      return { strategy: 'css', value: '[' + c.dataAttr + '="' + escaped + '"]' };
    }
    if (c.placeholder) return { strategy: 'placeholder', value: c.placeholder };
    if (c.id && !/[0-9a-f]{8,}|:/.test(c.id)) return { strategy: 'id', value: c.id };
    if (c.name) return { strategy: 'name', value: c.name };
    if (c.tag === 'button' && c.text) return { strategy: 'role', value: 'button:' + c.text };
    return { strategy: 'css', value: fallback };
  };

  return {
    username: locatorFor(username, 'input:not([type="hidden"]):not([type="password"])'),
    password: locatorFor(password, 'input[type="password"]'),
    submit: locatorFor(submit, 'button[type="submit"], input[type="submit"], button:not([type])'),
  };
}
// </tathya:login-infer>

/** The login page's controls, inferred from what it renders (the same rule the crawler uses). */
export async function inferLoginControls(page: Page): Promise<LoginControls> {
  await page.waitForLoadState('domcontentloaded').catch(() => undefined);
  // A client-rendered login page starts as an empty shell.
  await page.locator('input:not([type="hidden"])').first().waitFor({ timeout: 5000 }).catch(() => undefined);
  return page.evaluate(loginControlsOfDocument, null);
}

function cssEscape(value: string): string {
  return value.replaceAll('\\', '\\\\').replaceAll('"', '\\"');
}
